```go
package main

import "fmt"

type Point struct{ X, Y int }

func (p Point) Sum() int { return p.X + p.Y }

type Account struct{ Balance int }

func (a *Account) Deposit(amount int) { a.Balance += amount }

func main() {
    point := Point{X: 2, Y: 3}
    account := Account{Balance: 10}
    account.Deposit(5)
    fmt.Println(point.Sum(), account.Balance)
}
```
`Point.Sum` only observes a small value. `Account.Deposit` changes the original account and therefore uses `*Account`.

```go
package main

import "fmt"

type Box struct {
    Count  int
    Values []int
}

func (b Box) SetCount(n int) { b.Count = n }
func (b Box) SetFirst(n int) { b.Values[0] = n }

func main() {
    box := Box{Count: 1, Values: []int{2, 3}}
    box.SetCount(9)
    box.SetFirst(8)
    fmt.Println(box.Count, box.Values)
}
```
The output is `1 [8 3]`: the scalar field was changed only on the receiver copy, while both slice descriptors reached the same array.

```go
package main

import (
    "fmt"
    "sync"
)

type Counter struct {
    mu sync.Mutex
    n  int
}

func (c *Counter) Add() {
    c.mu.Lock()
    defer c.mu.Unlock()
    c.n++
}

func (c *Counter) Value() int {
    c.mu.Lock()
    defer c.mu.Unlock()
    return c.n
}

func main() {
    var counter Counter
    var workers sync.WaitGroup
    workers.Add(100)
    for i := 0; i < 100; i++ {
        go func() {
            defer workers.Done()
            counter.Add()
        }()
    }
    workers.Wait()
    fmt.Println(counter.Value())
}
```
The output is `100`. Both methods use `*Counter`, so all goroutines coordinate through the same mutex protecting the same `n` field.
